EXTS_NORMAL = ('.wsquashfs', '.squashfs', '.dwarfs', '.zip', '.7z', '.rar',
               '.001', '.z01', '.exe', '.bat', '.cmd', '.wtgz', '.sh',
               '.appimage', '.AppImage')

